function geometry() { const b = B(); restack(patches()); return { T: b.T, w: b.w, r0: R0, L: sheetLen(b) }; }
// ⚑ ПОТОЛОК ВИТКОВ 9 → 16 (02.09, #160). Девятка МОЛЧА СЪЕДАЛА ЛИСТ: намотка обрывалась на
// девятом витке, остаток длины никуда не девался, а просто не рисовался. Замер на узумаки с
// нори-носителем — 9,00 витка ровно (круглое число и есть подпись потолка) и 15,7 % площади
// среза в классе «снаружи»; с потолком 16 те же числа стали 9,85 витка и 3,3 %. То есть
// пропадала восьмая часть ролла, и ни одна мерка про это не говорила.
//
// Цена памяти прямая: массивы намотки — KMAX·NB чисел на ломтик, 207 КБ при девятке и 368 КБ
// при шестнадцати. Полную намотку строит windFor по требованию и только для рисуемого ломтика
// (см. комментарий у wind), так что это единицы, а не шестнадцать копий.
//
// ⚠ Потолок остаётся потолком: он не «достаточно большой», он просто больше. Поэтому в
// checks.js стоит мерка, которая ловит САМО УПИРАНИЕ — если намотка снова дойдёт до KMAX,
