// ⚠ ИСТОЧНИКА НЕТ, И ТЕПЕРЬ ИЗВЕСТНО, ЧТО ОН ПРОТИВ. Справочник приёмов нарезки разобран
// целиком (docs/ingredients.md, раздел 6-бис): двадцать три способа, и ни в одном не сказано,
// что ребро выходит скруглённым, — везде описан прямой ход ножа. Наблюдение, из которого фаска
