// начинка в ядре, бугра нет и ноль верен: ядро — это центр, а не слой. Но с правкой #141
// начинка может остаться ВНЕ ядра (когда коробка вытянута сверх 10:1), и тогда они оживают:
// замер на семи полосах по листу даёт `stackTopAt` 1,27 и `covers` = true.
