    for (let i = 0; i < M; i++) { маска[i] = a[i] > 1e-9 ? 1 : 0; массаДо += a[i] * cellWidth(i); }
    // ⚑ СГЛАЖИВАНИЕ НЕ ЗАГЛЯДЫВАЕТ ЗА КРАЙ НАМАЗКИ (правка 01.09, клюв нори у шва).
