    // до 85 % при потолке 8. Причина физическая, и она записана у повара — 「寿司飯と寿司飯の
    // 端を合わせて」: в кольце два конца постели ВСТРЕЧАЮТСЯ ТОРЦАМИ и вминаются друг в друга,
