    let Hоц = T; for (const p of все) Hоц = Math.max(Hоц, p.z1 * T);
    const предел = CORE_ASPECT_MAX * Math.max(T, Hоц);
    const с = все.map(p => { const w2 = dims(p, g, true).du * L / 2; return { p, s0: p.u * L - w2, s1: p.u * L + w2 }; })
