  // гр0 нужен coreMaterial как начало отсчёта по листу.
  const core = { sFold, fold, гр0, Wc: Math.max(гр1 - гр0, 1), items: [], HA: T, HB: 0 };
  // ⚑ ЯДРО — ОДНА ПОЛОСА, А НЕ СЛОЖЕННЫЙ ПАКЕТ (issue #134, правка 01.09 после кольца).
  //
  // Флаг `far` был не меткой ряда, а ВЫБОРОМ СИСТЕМЫ КООРДИНАТ: у ближней половины пакета
  // координата зеркалилась (`x0 = half − rg[1]`), потому что эта половина подвёрнута. Пока
  // намотка была спиралью с подворотом, это имело смысл.
  //
  // Кольцо (#132) подворот убрало, а ядро осталось сложенным — несогласованность после
  // вливания. Из-за неё кусок, доехавший до середины группы, скачком менял и ряд, и знак
  // координаты: замер дал шаг 0,40 на равномерном движении, и это владелец увидела как
  // «двигается по квадрату». Две попытки поменять правило ряда, не трогая координату,
  // кончились тем, что кусок улетал за пределы коробки и пропадал из среза совсем.
  //
  // Теперь ядро — просто связка: куски лежат в ряд по листу, высота берётся из стопки,
  // которую уже посчитал restack. Ни зеркала, ни половин.
  // ⚑ СКРУТКА СОБИРАЕТ НАЧИНКИ В ПУЧОК, А НЕ ОСТАВЛЯЕТ ПОЛОСОЙ (#152/#134, правка 02.09).
  //
  // Прежде коробка ядра брала габарит группы С ПЛОСКОГО ЛИСТА: четыре канонические начинки
  // давали 48 × 10 мм, вытянутость 4,8:1. Она же служила коэффициентом искажения, потому что
  // `coreMaterial` нормирует коробку в единичный квадрат ПО РАЗНЫМ ОСЯМ. Владелец увидела
  // следствие глазами: тот же тамаго один на листе — квадрат 12,4 × 12,0 мм, с тремя соседями
  // — полумесяц 7,5 × 23,5. Форма куска не может зависеть от числа соседей.
  //
  // На срезе настоящего футомаки начинки лежат КУЧКОЙ в два ряда, а не полосой: пока ролл
  // крутится, лист поджимает группу с обеих сторон и она собирается. Полоса — это след того,
  // что модель брала габарит до скрутки и не гнула его.
  //
  // ⚠ ДЕШЁВЫЙ ВАРИАНТ ПРОВЕРЕН И ОТВЕРГНУТ: ограничение вытянутости коробки (BUNDLE_MAX)
