    //
    // Замер после правки ядра показал, что розовый размазан по всем виткам ровной долей, и
    // напрашивалось объяснение «краска считается дважды — и в ядре, и в ленте». Пометка это
    // убрала, но сломала #95: при закрашенном до конца листе в намотке оставался белый рис,
    // 1112 точек — сторож поймал сразу.
    //
