  core.Hc = core.HA + core.HB + 2 * g.w;
  // ⚠ НАЧИНКИ В СГИБЕ НЕ ДОБАВЛЯЛИ ЯДРУ ОБЪЁМА ВОВСЕ — issue #1, найдено замером 31.08.
  //
