  // поднимали высоту ровно настолько, насколько поднял бы один, а их собственная площадь
  // пропадала. Замер на футомаки: ядро глотало 5,1 ед² начинок и росло на 1,3 ед².
  // Ровно то, о чём issue #1 — «вытесненный начинкой рис исчезает», — только не в постели,
  // а здесь: в постели течение уже починено (146234c), а в ядре нет.
  //
