  // coreMaterial отображает диск радиуса R в прямоугольник Wc × Hc целиком. Значит доля
  // любого куска в диске равна его доле в прямоугольнике. Если взять R из площади одного
  // ВЕЩЕСТВА (начинок), а прямоугольник оставить габаритным, начинки займут в диске лишь
  // свою долю от габарита — и уменьшатся вчетверо. Замер это и показал: 4,5 % вместо 24.
  // Поэтому R считается из того же прямоугольника, который отображается.
  // ⚑ ЯДРО — ЭТО САМА КОРОБКА, А НЕ РАВНОВЕЛИКИЙ ДИСК (#152, правка 02.09).
  //
  // Прежде коробка отображалась в круг: нормировка в единичный квадрат ПО РАЗНЫМ ОСЯМ, потом
  // почти конформное отображение Фонга. Искажение равнялось вытянутости коробки, и никакая
  // укладка от этого не спасает: плоские куски в квадратный пучок не складываются — лучшее
  // 2,4:1, и 2,4 остаётся коэффициентом. Замер обеих проб: полоса 4,8:1 давала дрейф формы
  // 3,3 раза, пучок 0,5:1 — 0,47, то есть перекос просто менял знак.
